# Code snippet to test the zip file conversion functionality
import zipfile
import io

def test_zip_conversion(zip_bytes):
    try:
        zip_file = zipfile.ZipFile(io.BytesIO(zip_bytes))
        text_content = []
        for zip_info in zip_file.infolist():
            if zip_info.filename.endswith('.txt'):
                with zip_file.open(zip_info) as text_file:
                    text_content.append(text_file.read().decode('utf-8'))
        return "\n".join(text_content)
    except zipfile.BadZipFile:
        return "Invalid zip file."
    except Exception as e:
        return
